            dockerImage.push(&quot;$BUILD_NUMBER&quot;)
             dockerImage.push('latest')

          }
        }
      }
    }
    stage('Deploy to K8s') {
      steps{
        script {
          sh &quot;sed -i 's,TEST_IMAGE_NAME,harshmanvar/node-web-app:$BUILD_NUMBER,' deployment.yaml&quot;
          sh &quot;cat deployment.yaml&quot;
