Q: Export module after promise completes
A: <h1>This is my code</h1>

<h2>read.js</h2>

<pre><code>var dir = require('node-dir');

var files = new Promise(function (resolve, reject) {
    dir.files('../sample/sample.txt', function (err, res){
        if (err) {
            reject(err);
            console.log('Oops, an error occured %s', err);
        }
        else {
            resolve(res);
        }
    });
});

exports.files = files;
</code></pre>

<p>And then use it as such on the file that imports this module.</p>

<h2>app.js</h2>

<pre><code>var read = require('read.js');

read.files.then(function(res) {
    console.log(res);
});
</code></pre>

<h1>Your revised code</h1>

<h2>read.js</h2>

<pre><code>var dir = require('node-dir');

var files = function(){
    return new Promise(function (resolve, reject) {
        dir.files('../sample/sample', function (err, res){
            if (err) {
                    reject(err);
                    console.log('Oops, an error occured %s', err);
            }
            else {
                      resolve(res);
                      return res;
              }
        });
    });
}

exports.files = files;
</code></pre>

<h2>app.js</h2>

<pre><code>var read = require('read.js');

read.files().then(function(res) {
    console.log(res);
});
</code></pre>

<p>Hope that helps.</p>

Q: NodeJS, JS how to export Promise value in a module, not the function?
A: <p>Two answers for you:</p>
<ul>
<li>With standard JavaScript modules (ESM)</li>
<li>With CommonJS (CJS), the module system you're using in the example in the question</li>
</ul>
<h2>With Standard JavaScript Modules (ESM)</h2>
<p>Now that support for ESM has matured, in most Node.js projects you can switch to ESM from CommonJS by putting <code>&quot;type&quot;: &quot;module&quot;</code> in your <code>package.json</code> and changing your <code>require()</code> calls to <code>import</code> statements as necessary. If you can do that, you can use <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/await#top_level_await" rel="nofollow noreferrer">top-level <code>await</code></a>. With top-level <code>await</code>, you can make your module execution wait for a promise to settle (which makes modules that import from your module wait until the promise settles). So you'd do this:</p>
<pre><code>function go() {
    return new Promise((resolve, reject) =&gt; {
        setTimeout(() =&gt; resolve(&quot;Success!&quot;), 500);
    });
}

export const AS = await go();
</code></pre>
<p>That exports a named export, but you could also replace that last line with this to do a default export (which is more similar to what you have in your CommonJS code; I prefer to avoid default exports):</p>
<pre><code>export default await go();
</code></pre>
<p>Modules using your module don't have to be aware of the fact that the value comes from an asynchronous

